<script setup lang="ts">
const auth = useAuth(); const api = useApi()
interface Entry { id: string; actor_type: string; actor_id: string | null; action: string; result: string; target_type: string | null; target_id: string | null; created_at: string; request_id: string | null }
const entries = ref<Entry[]>([]), busy = ref(false), error = ref('')
async function load() { busy.value = true; error.value = ''; try { entries.value = (await api.get<{ data: Entry[] }>('/security/audit?limit=100')).data } catch (e) { error.value = apiError(e).message } finally { busy.value = false } }
onMounted(() => { if (auth.can('security.audit.read')) void load() })
</script>
<template><div><h1>Журнал аудита</h1><p class="page-subtitle">Последние 100 событий. Журнал доступен только на чтение.</p><UiAlert v-if="!auth.can('security.audit.read')" tone="info" message="Недостаточно прав на просмотр аудита." /><template v-else><div class="toolbar"><span class="muted">События из PostgreSQL</span><button class="btn" :disabled="busy" @click="load">Обновить</button></div><UiAlert :message="error" /><section v-if="entries.length" class="panel table-wrap"><table class="table"><thead><tr><th>Время (UTC)</th><th>Действие</th><th>Результат</th><th>Субъект</th><th>Объект</th></tr></thead><tbody><tr v-for="entry in entries" :key="entry.id"><td class="small">{{ entry.created_at }}</td><td class="mono small">{{ entry.action }}</td><td><span :class="['tag', entry.result === 'success' ? 'good' : 'bad']">{{ entry.result }}</span></td><td class="mono small">{{ entry.actor_type }} {{ entry.actor_id }}</td><td class="mono small">{{ entry.target_type }} {{ entry.target_id }}</td></tr></tbody></table></section><div v-else-if="!busy" class="empty">События не найдены.</div></template></div></template>
